// Encrypted-PDF hardening (plan §12): the Standard-security-handler fixture
// generated by buildEncryptedPdf exercises the real pdf.js password path and
// the D2 no-copy permission end-to-end. Node env: pdf.js needs workers off.
// @vitest-environment node
import { describe, it, expect } from "vitest";
import { buildEncryptedPdf } from "../src/perf/synthPdf";
import { openPdf, classifyPdfError } from "../src/pdf/pdfjsAdapter";
import { parsePdf } from "../src/pdf/parsePdf";
import { COPY, ImportError, detectFormat } from "../src/import/fileDetector";

describe("buildEncryptedPdf fixture", () => {
  it("is byte-deterministic", () => {
    const a = buildEncryptedPdf({ userPassword: "folio-test", pages: 2, title: "Enc" });
    const b = buildEncryptedPdf({ userPassword: "folio-test", pages: 2, title: "Enc" });
    expect(Buffer.from(a).equals(Buffer.from(b))).toBe(true);
  });

  it("is detected as a PDF by magic bytes", () => {
    const bytes = buildEncryptedPdf({ userPassword: "pw", pages: 1 });
    expect(detectFormat("secret.pdf", bytes)).toBe("pdf");
  });
});

describe("openPdf password path (real pdf.js)", () => {
  it("refuses to open without a password", async () => {
    const bytes = buildEncryptedPdf({ userPassword: "folio-test", pages: 2 });
    await expect(openPdf(new Uint8Array(bytes))).rejects.toMatchObject({
      name: "PasswordException",
    });
  });

  it("rejects a wrong password with the INCORRECT_PASSWORD code", async () => {
    const bytes = buildEncryptedPdf({ userPassword: "right", pages: 1 });
    const error = await openPdf(new Uint8Array(bytes), { password: "wrong" }).then(
      () => null,
      (e: unknown) => e,
    );
    expect(error).toMatchObject({ name: "PasswordException", code: 2 });
    expect(classifyPdfError(error)?.code).toBe("encrypted");
  });

  it("opens with the correct password and decrypts page content", async () => {
    const bytes = buildEncryptedPdf({
      userPassword: "folio-test",
      pages: 2,
      title: "Enc",
      author: "Auth",
    });
    const { doc, destroy } = await openPdf(new Uint8Array(bytes), { password: "folio-test" });
    try {
      expect(doc.numPages).toBe(2);
      const page = await doc.getPage(1);
      const content = await page.getTextContent();
      const text = content.items.map((it) => ("str" in it ? it.str : "")).join("");
      expect(text).toContain("Page 1 of 2");
    } finally {
      await destroy();
    }
  });
});

describe("import pipeline refuses encrypted PDFs (v1.1 scope)", () => {
  it("parsePdf maps the password error to the user-facing refusal", async () => {
    const bytes = buildEncryptedPdf({ userPassword: "folio-test", pages: 1, title: "Secret" });
    await expect(parsePdf("secret.pdf", new Uint8Array(bytes))).rejects.toMatchObject({
      code: "encrypted",
      message: COPY.encrypted,
    });
  });

  it("the thrown error is an ImportError", async () => {
    const bytes = buildEncryptedPdf({ userPassword: "pw", pages: 1 });
    let caught: unknown = null;
    try {
      await parsePdf("secret.pdf", new Uint8Array(bytes));
    } catch (e) {
      caught = e;
    }
    expect(caught).toBeInstanceOf(ImportError);
  });
});

describe("D2: no-copy permissions end-to-end", () => {
  it("default permissions allow copying (bit 0x10 present)", async () => {
    const bytes = buildEncryptedPdf({ userPassword: "pw", pages: 1 });
    const { doc, destroy } = await openPdf(new Uint8Array(bytes), { password: "pw" });
    try {
      const perms = (await doc.getPermissions()) as Set<number> | null;
      expect(perms?.has(0x10)).toBe(true);
    } finally {
      await destroy();
    }
  });

  it("no-copy fixture clears COPY while keeping accessibility extraction", async () => {
    const bytes = buildEncryptedPdf({ userPassword: "pw", permissions: "no-copy", pages: 1 });
    const { doc, destroy } = await openPdf(new Uint8Array(bytes), { password: "pw" });
    try {
      const perms = (await doc.getPermissions()) as Set<number> | null;
      // COPY (0x10) denied…
      expect(perms?.has(0x10)).toBe(false);
      // …but accessibility / screen-reader extraction (0x200) stays granted —
      // the realistic "no copying" producer output D2 must respect.
      expect(perms?.has(0x200)).toBe(true);
    } finally {
      await destroy();
    }
  });
});
